/*
 * prog53_dfs_cycle – Detect a directed cycle in a graph of up to 8 vertices.
 *
 * The original binary expects the command‑line arguments to be a list of
 * integer pairs “src dst”.  Each pair describes a directed edge from
 * vertex *src* to vertex *dst*.  Vertices are numbered 0 … 7.
 *
 * Behaviour (as observed from the decompiled state‑machine):
 *
 *   * If the number of arguments after the program name is not even,
 *     or any argument cannot be parsed as a non‑negative integer,
 *     or any vertex number is outside the range [0,7],
 *     the program prints the literal string
 *
 *         INVALID_INPUT
 *
 *     and exits with status 1.
 *
 *   * Otherwise the program builds an adjacency matrix `adj[8][8]`
 *     where `adj[dst][src] = 1` for each supplied edge.
 *
 *   * It then runs a depth‑first search on the directed graph,
 *     using the classic colour‑based algorithm (0 = white,
 *     1 = gray, 2 = black).  If during the search it discovers a back‑edge
 *     (an edge to a gray vertex) it sets `found_cycle = true`.
 *
 *   * After the search finishes it prints either
 *
 *         CYCLE
 *
 *     if a directed cycle was found, or
 *
 *         ACYCLIC
 *
 *     otherwise, and returns 0.
 *
 * The implementation below reproduces exactly that observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>

#define MAXV 8                     /* maximum number of vertices */

static int  adj[MAXV][MAXV];        /* adjacency matrix */
static int  colour[MAXV];          /* 0 = white, 1 = gray, 2 = black */
static bool found_cycle = false;

/* Depth‑first search from vertex `v`. */
static void dfs(int v)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    colour[v] = 1;                 /* mark gray */

    for (int u = 0; u < MAXV; ++u) {
        if (adj[u][v] == 0)        /* no edge v → u */
            continue;

        if (colour[u] == 0) {     /* white – recurse */
            dfs(u);
            if (found_cycle)      /* propagate early exit */
                return;
        } else if (colour[u] == 1) {
            /* back‑edge to a gray vertex → cycle */
            found_cycle = true;
            return;
        }
        /* colour[u] == 2 (black) – already finished, nothing to do */
    }

    colour[v] = 2;                 /* mark black */
}

/* Helper: parse a string as a non‑negative integer, return -1 on error. */
static long parse_nonneg_int(const char *s)
{
    char *endptr;
    errno = 0;
    long val = strtol(s, &endptr, 10);
    if (errno != 0 || *endptr != '\0' || val < 0)
        return -1;
    return val;
}

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     *  Input validation
     * ----------------------------------------------------------------- */
    if ((argc - 1) % 2 != 0) {          /* must be an even number of ints */
        puts("INVALID_INPUT");
        return 1;
    }

    /* Initialise data structures */
    memset(adj, 0, sizeof(adj));
    memset(colour, 0, sizeof(colour));
    found_cycle = false;

    /* -----------------------------------------------------------------
     *  Build adjacency matrix
     * ----------------------------------------------------------------- */
    int edge_cnt = (argc - 1) / 2;      /* number of (src,dst) pairs */
    for (int i = 0; i < edge_cnt; ++i) {
        const char *src_str = argv[2 * i + 1];
        const char *dst_str = argv[2 * i + 2];

        long src = parse_nonneg_int(src_str);
        long dst = parse_nonneg_int(dst_str);

        if (src < 0 || dst < 0 || src >= MAXV || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* Store edge src → dst as adj[dst][src] = 1 (the original binary
         * used this layout). */
        adj[dst][src] = 1;
    }

    /* -----------------------------------------------------------------
     *  Cycle detection (DFS from every unvisited vertex)
     * ----------------------------------------------------------------- */
    for (int v = 0; v < MAXV && !found_cycle; ++v) {
        if (colour[v] == 0)
            dfs(v);
    }

    /* -----------------------------------------------------------------
     *  Output result
     * ----------------------------------------------------------------- */
    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
